/work/lib/validation/bookmark.ts.content:
import { z } from "zod";
import { normalizeBookmarkUrl, normalizeTag, normalizeTitle } from "@/lib/domain/normalization";

export const bookmarkInputSchema = z.object({
  title: z.string().transform(normalizeTitle).pipe(z.string().min(1, "Enter a title.").max(200, "Keep the title to 200 characters or fewer.")),
  url: z.string().transform((value, ctx) => {
    try { return normalizeBookmarkUrl(value); } catch (error) { ctx.addIssue({ code: "custom", message: error instanceof Error ? error.message : "Enter a valid web address." }); return z.NEVER; }
  }),
  tags: z.array(z.string()).max(20, "Use no more than 20 tags.").transform((values, ctx) => {
    const normalized = values.filter((value) => value.trim()).map(normalizeTag);
    const unique = [...new Map(normalized.map((tag) => [tag.normalizedName, tag])).values()];
    for (const tag of unique) if (!tag.name || tag.name.length > 50) ctx.addIssue({ code: "custom", message: "Each tag must be between 1 and 50 characters." });
    return unique;
  })
}).strict();

export type BookmarkInput = z.infer<typeof bookmarkInputSchema>;

/work/lib/http/problem.ts.content:
import { NextResponse } from "next/server";

export function problem(status: number, code: string, message: string, extra: Record<string, unknown> = {}) {
  return NextResponse.json({ code, message, ...extra }, { status, headers: { "Cache-Control": "private, no-store" } });
}

export function privateJson(data: unknown, init: ResponseInit = {}) {
  return NextResponse.json(data, { ...init, headers: { ...init.headers, "Cache-Control": "private, no-store" } });
}

/work/lib/db/schema.ts.content:
import { pgTable, text, timestamp, primaryKey, uniqueIndex, index } from "drizzle-orm/pg-core";

export const users = pgTable("users", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull(),
  passwordHash: text("password_hash").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow()
}, (table) => [uniqueIndex("users_email_unique").on(table.email)]);

export const sessions = pgTable("sessions", {
  id: text("id").primaryKey(),
  tokenHash: text("token_hash").notNull(),
  userId: text("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow()
}, (table) => [uniqueIndex("sessions_token_hash_unique").on(table.tokenHash), index("sessions_user_idx").on(table.userId)]);

export const bookmarks = pgTable("bookmarks", {
  id: text("id").primaryKey(),
  ownerId: text("owner_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  title: text("title").notNull(),
  url: text("url").notNull(),
  normalizedUrl: text("normalized_url").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow()
}, (table) => [
  uniqueIndex("bookmarks_owner_url_unique").on(table.ownerId, table.normalizedUrl),
  index("bookmarks_owner_created_idx").on(table.ownerId, table.createdAt, table.id)
]);

export const tags = pgTable("tags", {
  id: text("id").primaryKey(),
  ownerId: text("owner_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  normalizedName: text("normalized_name").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow()
}, (table) => [uniqueIndex("tags_owner_name_unique").on(table.ownerId, table.normalizedName)]);

export const bookmarkTags = pgTable("bookmark_tags", {
  bookmarkId: text("bookmark_id").notNull().references(() => bookmarks.id, { onDelete: "cascade" }),
  tagId: text("tag_id").notNull().references(() => tags.id, { onDelete: "cascade" })
}, (table) => [primaryKey({ columns: [table.bookmarkId, table.tagId] }), index("bookmark_tags_tag_idx").on(table.tagId, table.bookmarkId)]);

/work/lib/domain/normalization.ts.content:
export function collapseWhitespace(value: string) {
  return value.trim().replace(/\s+/gu, " ");
}

export function normalizeTitle(value: string) {
  return collapseWhitespace(value);
}

export function normalizeTag(value: string) {
  const name = collapseWhitespace(value).normalize("NFC");
  return { name, normalizedName: name.toLocaleLowerCase("en-US") };
}

export function normalizeBookmarkUrl(value: string) {
  const input = value.trim();
  if (!input || input.length > 2048) throw new Error("Enter a web address up to 2,048 characters.");
  let parsed: URL;
  try { parsed = new URL(input); } catch { throw new Error("Enter a complete web address, such as https://example.com."); }
  if (!["http:", "https:"].includes(parsed.protocol)) throw new Error("Only http and https web addresses can be saved.");
  if (!parsed.hostname) throw new Error("The web address must include a host name.");
  if (parsed.username || parsed.password) throw new Error("Web addresses containing usernames or passwords cannot be saved.");
  return { url: parsed.href, normalizedUrl: parsed.href };
}

/work/lib/auth/server.ts.content:
import { cookies } from "next/headers";
import { createHash, randomBytes, randomUUID, scryptSync, timingSafeEqual } from "node:crypto";
import { and, eq, gt } from "drizzle-orm";
import { db, ensureDatabase } from "@/lib/db/client";
import { sessions, users } from "@/lib/db/schema";

const COOKIE = "bookmark_session";
const SESSION_DAYS = 7;
const hashToken = (token: string) => createHash("sha256").update(token).digest("hex");

export function hashPassword(password: string) {
  const salt = randomBytes(16).toString("hex");
  return `${salt}:${scryptSync(password, salt, 64).toString("hex")}`;
}

export function verifyPassword(password: string, stored: string) {
  const [salt, expectedHex] = stored.split(":");
  if (!salt || !expectedHex) return false;
  const actual = scryptSync(password, salt, 64);
  const expected = Buffer.from(expectedHex, "hex");
  return actual.length === expected.length && timingSafeEqual(actual, expected);
}

export async function createSession(userId: string) {
  await ensureDatabase();
  const token = randomBytes(32).toString("base64url");
  const expiresAt = new Date(Date.now() + SESSION_DAYS * 86400000);
  await db.insert(sessions).values({ id: randomUUID(), tokenHash: hashToken(token), userId, expiresAt });
  const jar = await cookies();
  jar.set(COOKIE, token, { httpOnly: true, secure: process.env.NODE_ENV === "production", sameSite: "lax", path: "/", expires: expiresAt });
}

export async function destroySession() {
  await ensureDatabase();
  const jar = await cookies();
  const token = jar.get(COOKIE)?.value;
  if (token) await db.delete(sessions).where(eq(sessions.tokenHash, hashToken(token)));
  jar.delete(COOKIE);
}

export async function getCurrentUser() {
  await ensureDatabase();
  const token = (await cookies()).get(COOKIE)?.value;
  if (!token) return null;
  const rows = await db.select({ id: users.id, name: users.name, email: users.email }).from(sessions)
    .innerJoin(users, eq(users.id, sessions.userId))
    .where(and(eq(sessions.tokenHash, hashToken(token)), gt(sessions.expiresAt, new Date()))).limit(1);
  return rows[0] ?? null;
}

