const emptyDraft: Draft = { title: "", url: "", tags: "" };

export function BookmarkCollection({ user }: { user: { id: string; name: string; email: string } }) {
  const router = useRouter(); const [items, setItems] = useState<Bookmark[]>([]); const [allTags, setAllTags] = useState<Tag[]>([]); const [draft, setDraft] = useState(emptyDraft); const [editing, setEditing] = useState<Bookmark | null>(null); const [deleting, setDeleting] = useState<Bookmark | null>(null); const [query, setQuery] = useState(""); const [tagId, setTagId] = useState(""); const [status, setStatus] = useState(""); const [error, setError] = useState(""); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const dialogRef = useRef<HTMLDialogElement>(null);
  const load = useCallback(async (q = query, tag = tagId) => { const response = await fetch(`/api/bookmarks?q=${encodeURIComponent(q)}&tagId=${encodeURIComponent(tag)}`, { cache: "no-store" }); if (response.status === 401) { router.push("/login"); return; } const data = await response.json(); setItems(data.items ?? []); setLoading(false); const tagsResponse = await fetch("/api/tags", { cache: "no-store" }); if (tagsResponse.ok) setAllTags((await tagsResponse.json()).items); }, [query, tagId, router]);
  useEffect(() => { const timer = setTimeout(() => void load(query, tagId), 250); return () => clearTimeout(timer); }, [query, tagId, load]);
  useEffect(() => { if (deleting) { dialogRef.current?.showModal(); setTimeout(() => dialogRef.current?.querySelector<HTMLButtonElement>("[data-cancel]")?.focus(), 0); } }, [deleting]);
  function payload(value: Draft) { return { title: value.title, url: value.url, tags: value.tags.split(",").map((tag) => tag.trim()).filter(Boolean) }; }
  async function save(event: FormEvent) { event.preventDefault(); setError(""); setBusy(true); const target = editing ? `/api/bookmarks/${editing.id}` : "/api/bookmarks"; const response = await fetch(target, { method: editing ? "PUT" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload(draft)) }); if (!response.ok) { setError((await response.json()).message ?? "Your changes could not be saved."); setBusy(false); return; } const action = editing ? "updated" : "saved"; setDraft(emptyDraft); setEditing(null); setBusy(false); setStatus(`Bookmark ${action}.`); await load(); }
  function beginEdit(item: Bookmark) { setEditing(item); setDraft({ title: item.title, url: item.url, tags: item.tags.map((tag) => tag.name).join(", ") }); setError(""); document.querySelector("#save-heading")?.scrollIntoView({ behavior: "smooth" }); }
  async function confirmDelete() { if (!deleting) return; const response = await fetch(`/api/bookmarks/${deleting.id}`, { method: "DELETE" }); if (response.ok) { setStatus(`Deleted ${deleting.title}.`); setDeleting(null); dialogRef.current?.close(); await load(); document.querySelector<HTMLButtonElement>("[data-first-action]")?.focus(); } else setStatus("The bookmark could not be deleted."); }
  async function logout() { await fetch("/api/auth/logout", { method: "POST" }); router.push("/login"); router.refresh(); }
  const filtered = query || tagId;
  return <div className="app-shell" data-harness-ready={!loading ? "true" : undefined}><header className="topbar"><a className="brand" href="/bookmarks">KEPT<span>.</span></a><div className="header-actions"><span className="user-chip" aria-label={`Signed in as ${user.name}`}>{user.name.slice(0,1).toUpperCase()}</span><button className="button text" onClick={logout}>Sign out</button></div></header><main id="main"><section className="hero"><div><p className="eyebrow">YOUR LIBRARY</p><h1>Things worth<br/><em>coming back to.</em></h1><p className="muted hero-copy">Save the good stuff. Find it when you need it.</p></div><form className="save-card" onSubmit={save} noValidate><div className="card-heading"><div><p className="eyebrow">{editing ? "EDIT BOOKMARK" : "QUICK SAVE"}</p><h2 id="save-heading">{editing ? "Update this link" : "Keep something good"}</h2></div><span className="spark" aria-hidden="true">✦</span></div><label>Web address<input autoFocus={!editing} type="url" value={draft.url} onChange={(e) => setDraft({ ...draft, url: e.target.value })} placeholder="https://…" required/></label><label>Title<input value={draft.title} onChange={(e) => setDraft({ ...draft, title: e.target.value })} placeholder="What should you call it?" required maxLength={200}/></label><label>Tags <span className="hint">comma separated</span><input value={draft.tags} onChange={(e) => setDraft({ ...draft, tags: e.target.value })} placeholder="design, reading, useful"/></label>{error && <p className="form-error" role="alert">{error}</p>}<div className="form-actions"><button className="button primary" disabled={busy}>{busy ? "Saving…" : editing ? "Save changes" : "Save bookmark"}</button>{editing && <button type="button" className="button secondary" onClick={() => { setEditing(null); setDraft(emptyDraft); setError(""); }}>Cancel</button>}</div></form></section><section className="library-section"><div className="library-head"><div><p className="eyebrow">THE COLLECTION</p><h2>{items.length ? `${items.length} ${items.length === 1 ? "bookmark" : "bookmarks"}` : "Your bookmarks"}</h2></div><div className="filters"><label className="search"><span className="sr-only">Search bookmarks</span><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search your library…"/><span aria-hidden="true">⌕</span></label><label><span className="sr-only">Filter by tag</span><select value={tagId} onChange={(e) => setTagId(e.target.value)}><option value="">All tags</option>{allTags.map((tag) => <option key={tag.id} value={tag.id}>{tag.name}</option>)}</select></label>{filtered && <button className="button text" onClick={() => { setQuery(""); setTagId(""); }}>Clear</button>}</div></div>{loading ? <div className="empty"><p>Opening your library…</p></div> : items.length === 0 ? <div className="empty"><span aria-hidden="true">◇</span><h3>{filtered ? "Nothing matches that search" : "A fresh shelf"}</h3><p>{filtered ? "Try another phrase or clear your filters." : "Save your first link above. This is where the good stuff will gather."}</p>{filtered && <button className="button secondary" onClick={() => { setQuery(""); setTagId(""); }}>Clear search and filters</button>}</div> : <div className="bookmark-grid">{items.map((item, index) => <article className="bookmark-card" key={item.id} tabIndex={-1} id={`bookmark-${item.id}`}><div className="bookmark-main"><div className="domain">{new URL(item.url).hostname.replace(/^www\./, "")}</div><h3><a href={item.url} target="_blank" rel="noopener noreferrer">{item.title}<span aria-hidden="true">↗</span></a></h3><p className="url">{item.url}</p>{item.tags.length > 0 && <div className="tag-list">{item.tags.map((tag) => <button key={tag.id} onClick={() => setTagId(tag.id)}>#{tag.name}</button>)}</div>}</div><footer><span>Saved {new Intl.DateTimeFormat("en", { month: "short", day: "numeric", year: "numeric" }).format(new Date(item.createdAt))}</span><div><button data-first-action={index === 0 ? "true" : undefined} className="icon-button" onClick={() => beginEdit(item)} aria-label={`Edit ${item.title}`}>Edit</button><button className="icon-button danger" onClick={() => setDeleting(item)} aria-label={`Delete ${item.title}`}>Delete</button></div></footer></article>)}</div>}</section></main><p className="sr-only" aria-live="polite" aria-atomic="true">{status}{!loading && ` ${items.length} results.`}</p><dialog ref={dialogRef} className="delete-dialog" onCancel={(e) => { e.preventDefault(); setDeleting(null); dialogRef.current?.close(); }}><p className="eyebrow">CONFIRM DELETE</p><h2>Let this one go?</h2><p><strong>{deleting?.title}</strong> will be removed from your library. This can’t be undone.</p><div className="dialog-actions"><button data-cancel className="button secondary" onClick={() => { setDeleting(null); dialogRef.current?.close(); }}>Cancel</button><button className="button danger-fill" onClick={confirmDelete}>Delete bookmark</button></div></dialog></div>;
}

