import { test, expect } from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";

test("complete private bookmark journey by keyboard-friendly controls", async ({ page }) => {
  const email = `reader-${Date.now()}@example.com`;
  await page.goto("/register");
  await page.getByLabel("Your name").fill("Test Reader");
  await page.getByLabel("Email address").fill(email);
  await page.getByLabel("Password").fill("CorrectHorse123!");
  await page.getByRole("button", { name: "Create account" }).click();
  await expect(page).toHaveURL(/\/bookmarks/);
  await page.getByLabel("Web address").fill("HTTP://Example.com:80");
  await page.getByLabel("Title").fill("Example reference");
  await page.getByLabel(/Tags/).fill("Reading, useful");
  await page.getByRole("button", { name: "Save bookmark" }).click();
  await expect(page.getByRole("link", { name: /Example reference/ })).toBeVisible();
  await page.getByPlaceholder("Search your library…").fill("useful");
  await expect(page.getByRole("link", { name: /Example reference/ })).toBeVisible();
  await page.getByRole("button", { name: /Edit Example reference/ }).click();
  await page.getByLabel("Title").fill("Edited reference");
  await page.getByRole("button", { name: "Save changes" }).click();
  await expect(page.getByRole("link", { name: /Edited reference/ })).toBeVisible();
  await page.getByRole("button", { name: /Delete Edited reference/ }).click();
  await expect(page.getByRole("dialog")).toBeVisible();
  await page.keyboard.press("Escape");
  await expect(page.getByRole("dialog")).not.toBeVisible();
  await page.getByRole("button", { name: /Delete Edited reference/ }).click();
  await page.getByRole("button", { name: "Delete bookmark" }).click();
  await expect(page.getByText("A fresh shelf")).toBeVisible();
  const results = await new AxeBuilder({ page }).analyze();
  expect(results.violations).toEqual([]);
});

/work/tests/unit/normalization.test.ts.content:
import { describe, expect, it } from "vitest";
import { normalizeBookmarkUrl, normalizeTag, normalizeTitle } from "@/lib/domain/normalization";

describe("bookmark normalization", () => {
  it("normalizes unambiguous URL equivalents", () => expect(normalizeBookmarkUrl(" HTTP://Example.com:80 ").normalizedUrl).toBe("http://example.com/"));
  it("preserves meaningful query order and fragments", () => {
    expect(normalizeBookmarkUrl("https://example.com/?a=1&b=2#one").normalizedUrl).not.toBe(normalizeBookmarkUrl("https://example.com/?b=2&a=1#two").normalizedUrl);
  });
  it.each(["javascript:alert(1)", "ftp://example.com", "https://user:pass@example.com"])("rejects unsafe URL %s", (url) => expect(() => normalizeBookmarkUrl(url)).toThrow());
  it("collapses title and tag whitespace and folds tag case", () => {
    expect(normalizeTitle("  A   good title ")).toBe("A good title");
    expect(normalizeTag("  DeSign ")).toEqual({ name: "DeSign", normalizedName: "design" });
  });
});

/work/tests/unit/bookmark-validation.tes.content:
import { describe, expect, it } from "vitest";
import { bookmarkInputSchema } from "@/lib/validation/bookmark";

describe("bookmark input", () => {
  it("accepts valid input and merges equivalent tags", () => {
    const value = bookmarkInputSchema.parse({ title: "Example", url: "https://example.com", tags: ["Read", " read "] });
    expect(value.tags).toHaveLength(1);
  });
  it("enforces field limits", () => {
    expect(bookmarkInputSchema.safeParse({ title: "x".repeat(201), url: "https://example.com", tags: [] }).success).toBe(false);
    expect(bookmarkInputSchema.safeParse({ title: "Ok", url: "https://example.com", tags: Array.from({ length: 21 }, (_, i) => `tag${i}`) }).success).toBe(false);
  });
});

